def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous non-background runs along each of the four borders.
    borders = {
        "top": [(0, c) for c in range(w)],
        "bottom": [(h - 1, c) for c in range(w)],
        "left": [(r, 0) for r in range(h)],
        "right": [(r, w - 1) for r in range(h)],
    }
    runs = {side: [] for side in borders}
    border_cells = set()
    for side, coords in borders.items():
        i = 0
        while i < len(coords):
            r, c = coords[i]
            color = grid[r][c]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(coords) and grid[coords[j][0]][coords[j][1]] == color:
                j += 1
            if j - i >= 2:
                runs[side].append((color, i, j))
                border_cells.update(coords[i:j])
            i = j

    # Pair congruent bars on opposite sides (same color and length).
    pairings = []
    for side1, side2 in (("top", "bottom"), ("left", "right")):
        for a in runs[side1]:
            for b in runs[side2]:
                if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                    pairings.append((side1, side2, a, b))

    def edge_cell(side, k):
        if side == "top": return (0, k)
        if side == "bottom": return (h - 1, k)
        if side == "left": return (k, 0)
        return (k, w - 1)

    def inward(side):
        return {"top": (1, 0), "bottom": (-1, 0),
                "left": (0, 1), "right": (0, -1)}[side]

    def paint_ray(side, lane, color, stop_at_marker=None):
        r, c = edge_cell(side, lane)
        dr, dc = inward(side)
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value != bg:
                if stop_at_marker == (r, c):
                    out[r][c] = 4
                break
            out[r][c] = color
            r += dr
            c += dc

    # Every interior non-background mark lying in a bar's lane selects that
    # offset: the mark is connected to its own bar, and the opposite bar emits
    # a full ray in the matching relative lane.
    for r in range(h):
        for c in range(w):
            marker_color = grid[r][c]
            if marker_color == bg or (r, c) in border_cells:
                continue
            for side1, side2, a, b in pairings:
                if side1 in ("top", "bottom"):
                    pos = c
                    own_side = side1 if a[1] <= pos < a[2] else side2 if b[1] <= pos < b[2] else None
                else:
                    pos = r
                    own_side = side1 if a[1] <= pos < a[2] else side2 if b[1] <= pos < b[2] else None
                if own_side is None:
                    continue
                own_run, other_run = (a, b) if own_side == side1 else (b, a)
                other_side = side2 if own_side == side1 else side1
                offset = pos - own_run[1]
                own_lane = own_run[1] + offset
                other_lane = other_run[1] + offset
                # Ray from the marker's corresponding border bar, stopping at it.
                sr, sc = edge_cell(own_side, own_lane)
                dr, dc = inward(own_side)
                rr, cc = sr + dr, sc + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if (rr, cc) == (r, c):
                        out[r][c] = 4
                        break
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = marker_color
                    rr += dr
                    cc += dc
                # Matching lane from the opposite bar continues until an object
                # or the edge; its own border bar is never overwritten.
                paint_ray(other_side, other_lane, marker_color)
                break
    return out
